package com.worldexamine;

class ActiveExamine
{
	private final String text;
	private final ExamineTarget target;
	private final long createdAt;
	private final long expiresAt;
	private long dismissStartedAt = -1L;

	ActiveExamine(String text, ExamineTarget target, long createdAt, long expiresAt)
	{
		this.text = text;
		this.target = target;
		this.createdAt = createdAt;
		this.expiresAt = expiresAt;
	}

	String getText()
	{
		return text;
	}

	ExamineTarget getTarget()
	{
		return target;
	}

	long getCreatedAt()
	{
		return createdAt;
	}

	long getExpiresAt()
	{
		return expiresAt;
	}

	void beginDismiss(long now)
	{
		if (dismissStartedAt < 0L)
		{
			dismissStartedAt = now;
		}
	}

	boolean isDismissing()
	{
		return dismissStartedAt >= 0L;
	}

	long getDismissStartedAt()
	{
		return dismissStartedAt;
	}
}

package com.worldexamine;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import javax.annotation.Nullable;
import net.runelite.api.Actor;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.widgets.Widget;

final class ExamineTarget
{
	enum Kind
	{
		ACTOR,
		TILE_OBJECT,
		WIDGET
	}

	private final Kind kind;
	private final Actor actor;
	private final TileObject tileObject;
	private final Widget widget;

	private ExamineTarget(Kind kind, Actor actor, TileObject tileObject, Widget widget)
	{
		this.kind = kind;
		this.actor = actor;
		this.tileObject = tileObject;
		this.widget = widget;
	}

	static ExamineTarget actor(Actor actor)
	{
		return new ExamineTarget(Kind.ACTOR, actor, null, null);
	}

	static ExamineTarget tileObject(TileObject tileObject)
	{
		return new ExamineTarget(Kind.TILE_OBJECT, null, tileObject, null);
	}

	static ExamineTarget widget(Widget widget)
	{
		return new ExamineTarget(Kind.WIDGET, null, null, widget);
	}

	@Nullable
	Point getTextLocation(Graphics2D graphics, String text, int extraHeight)
	{
		switch (kind)
		{
			case ACTOR:
				if (actor == null)
				{
					return null;
				}
				return actor.getCanvasTextLocation(graphics, text,
					Math.max(0, actor.getLogicalHeight()) + extraHeight);

			case TILE_OBJECT:
				if (tileObject == null)
				{
					return null;
				}

				// Prefer the top of the rendered object's clickbox. This keeps the
				// examine sentence visually above tall scenery instead of near its tile.
				Shape clickbox = tileObject.getClickbox();
				if (clickbox != null)
				{
					Rectangle bounds = clickbox.getBounds();
					if (!bounds.isEmpty())
					{
						int width = graphics.getFontMetrics().stringWidth(text);
						return new Point(bounds.x + (bounds.width - width) / 2, bounds.y - extraHeight);
					}
				}

				return tileObject.getCanvasTextLocation(graphics, text, extraHeight);

			case WIDGET:
				if (widget == null || widget.isHidden())
				{
					return null;
				}
				Point topLeft = widget.getCanvasLocation();
				if (topLeft == null)
				{
					return null;
				}
				Rectangle bounds = new Rectangle(topLeft.getX(), topLeft.getY(), widget.getWidth(), widget.getHeight());
				int width = graphics.getFontMetrics().stringWidth(text);
				return new Point(bounds.x + (bounds.width - width) / 2, bounds.y - extraHeight);

			default:
				return null;
		}
	}

	boolean sameTarget(ExamineTarget other)
	{
		if (other == null || kind != other.kind)
		{
			return false;
		}

		switch (kind)
		{
			case ACTOR:
				return actor == other.actor;
			case TILE_OBJECT:
				return tileObject == other.tileObject;
			case WIDGET:
				return widget == other.widget;
			default:
				return false;
		}
	}
}

