package com.worldexamine;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(WorldExamineConfig.GROUP)
public interface WorldExamineConfig extends Config
{
	String GROUP = "world-examine";

	@ConfigItem(
		keyName = "hideChat",
		name = "Hide chat examine",
		description = "Remove normal item, NPC, and object examine messages from the chatbox"
	)
	default boolean hideChat()
	{
		return true;
	}

	@ConfigItem(
		keyName = "duration",
		name = "Display time",
		description = "How long examine text remains visible, in milliseconds"
	)
	@Range(min = 1000, max = 10000)
	default int duration()
	{
		return 4000;
	}

	@ConfigItem(
		keyName = "fadeDuration",
		name = "Fade time",
		description = "How long the examine text fades out at the end, in milliseconds"
	)
	@Range(min = 0, max = 3000)
	default int fadeDuration()
	{
		return 650;
	}

	@ConfigItem(
		keyName = "replacementFadeDuration",
		name = "Replacement fade",
		description = "How quickly older examine text fades when a new examine appears, in milliseconds"
	)
	@Range(min = 80, max = 1000)
	default int replacementFadeDuration()
	{
		return 260;
	}

	@ConfigItem(
		keyName = "replacementLift",
		name = "Replacement lift",
		description = "How many pixels older examine text drifts upward while fading"
	)
	@Range(min = 0, max = 40)
	default int replacementLift()
	{
		return 8;
	}

	@Alpha
	@ConfigItem(
		keyName = "textColor",
		name = "Text colour",
		description = "Colour of examine text above the target"
	)
	default Color textColor()
	{
		return new Color(255, 255, 255, 255);
	}

	@ConfigItem(
		keyName = "fontSize",
		name = "Font size",
		description = "Size of the examine text"
	)
	@Range(min = 10, max = 24)
	default int fontSize()
	{
		return 16;
	}

	@ConfigItem(
		keyName = "maxWidth",
		name = "Maximum width",
		description = "Maximum width of a line before long examines wrap"
	)
	@Range(min = 120, max = 600)
	default int maxWidth()
	{
		return 320;
	}

	@ConfigItem(
		keyName = "verticalOffset",
		name = "Vertical offset",
		description = "Additional height above the examined target"
	)
	@Range(min = -50, max = 250)
	default int verticalOffset()
	{
		return 18;
	}
}

package com.worldexamine;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class WorldExamineOverlay extends Overlay
{
	private final WorldExaminePlugin plugin;
	private final WorldExamineConfig config;

	@Inject
	WorldExamineOverlay(WorldExaminePlugin plugin, WorldExamineConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		long now = System.currentTimeMillis();
		plugin.removeExpired(now);

		Font oldFont = graphics.getFont();
		Composite oldComposite = graphics.getComposite();
		graphics.setFont(oldFont.deriveFont(Font.PLAIN, (float) config.fontSize()));

		for (ActiveExamine examine : plugin.getActiveExamines())
		{
			renderExamine(graphics, examine, now);
		}

		graphics.setComposite(oldComposite);
		graphics.setFont(oldFont);
		return null;
	}

	private void renderExamine(Graphics2D graphics, ActiveExamine examine, long now)
	{
		long remaining = examine.getExpiresAt() - now;
		if (remaining <= 0)
		{
			return;
		}

		Color base = config.textColor();
		float fade = 1.0f;
		int lift = 0;

		if (examine.isDismissing())
		{
			int replacementFadeDuration = Math.max(1, config.replacementFadeDuration());
			float progress = Math.max(0.0f, Math.min(1.0f,
				(now - examine.getDismissStartedAt()) / (float) replacementFadeDuration));

			// Smoothstep gives the dismissal a softer, less linear feel.
			float eased = progress * progress * (3.0f - 2.0f * progress);
			fade = 1.0f - eased;
			lift = Math.round(config.replacementLift() * eased);
		}
		else
		{
			int fadeDuration = config.fadeDuration();
			if (fadeDuration > 0 && remaining < fadeDuration)
			{
				fade = Math.max(0.0f, Math.min(1.0f, remaining / (float) fadeDuration));
			}
		}

		Color color = base;

		List<String> lines = wrap(graphics.getFontMetrics(), examine.getText(), config.maxWidth());
		int lineHeight = graphics.getFontMetrics().getHeight();

		Composite previousComposite = graphics.getComposite();
		graphics.setComposite(AlphaComposite.SrcOver.derive(fade));

		for (int i = 0; i < lines.size(); i++)
		{
			String line = lines.get(i);
			Point point = examine.getTarget().getTextLocation(
				graphics,
				line,
				config.verticalOffset());
			if (point != null)
			{
				int stackHeight = (lines.size() - 1 - i) * lineHeight;
				int x = point.getX();
				int y = point.getY() - stackHeight - lift;

				graphics.setColor(new Color(0, 0, 0, base.getAlpha()));
				graphics.drawString(line, x + 1, y + 1);
				graphics.setColor(color);
				graphics.drawString(line, x, y);
			}
		}

		graphics.setComposite(previousComposite);
	}

	private static List<String> wrap(FontMetrics metrics, String text, int maxWidth)
	{
		List<String> lines = new ArrayList<>();
		if (text == null || text.isEmpty())
		{
			return lines;
		}

		String[] words = text.split("\\s+");
		StringBuilder line = new StringBuilder();
		for (String word : words)
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (line.length() > 0 && metrics.stringWidth(candidate) > maxWidth)
			{
				lines.add(line.toString());
				line.setLength(0);
				line.append(word);
			}
			else
			{
				if (line.length() > 0)
				{
					line.append(' ');
				}
				line.append(word);
			}
		}

		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}
}

package com.worldexamine;

import com.google.inject.Provides;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.ItemLayer;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "World Examine",
	description = "Displays examine text above NPCs, objects, and items instead of the chatbox",
	tags = {"examine", "overhead", "overlay", "npc", "object", "item"}
)
public class WorldExaminePlugin extends Plugin
{
	private static final int MAX_PENDING = 10;
	private static final int MAX_ACTIVE = 8;
	private static final long PENDING_TIMEOUT_MS = 5000L;

	private final Deque<PendingExamine> pendingExamines = new ArrayDeque<>();
	private final List<ActiveExamine> activeExamines = new ArrayList<>();

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private WorldExamineOverlay overlay;

	@Inject
	private WorldExamineConfig config;

	@Provides
	WorldExamineConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WorldExamineConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		pendingExamines.clear();
		activeExamines.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		pendingExamines.clear();
		activeExamines.clear();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!"Examine".equalsIgnoreCase(Text.removeTags(event.getMenuOption())))
		{
			return;
		}

		PendingExamine pending = createPending(event);
		if (pending == null)
		{
			return;
		}

		long now = System.currentTimeMillis();
		prunePending(now);
		pendingExamines.addLast(pending);
		while (pendingExamines.size() > MAX_PENDING)
		{
			pendingExamines.removeFirst();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (!isExamineType(type))
		{
			return;
		}

		long now = System.currentTimeMillis();
		prunePending(now);
		PendingExamine pending = removeFirstMatching(type);
		boolean displayed = false;
		if (pending != null)
		{
			String text = Text.removeTags(event.getMessage()).trim();
			if (!text.isEmpty())
			{
				// A new examine should visually take precedence. Rather than abruptly
				// removing older text, put every existing examine into a short
				// dismiss animation so rapid back-to-back examines never stack messily.
				for (ActiveExamine active : activeExamines)
				{
					active.beginDismiss(now);
				}

				activeExamines.add(new ActiveExamine(
					text,
					pending.getTarget(),
					now,
					now + config.duration()));
				while (activeExamines.size() > MAX_ACTIVE)
				{
					activeExamines.remove(0);
				}
				displayed = true;
			}
		}

		// Only hide the original chat line if we successfully created an overhead
		// examine. Unsupported examine targets should still fall back to chat.
		if (displayed && config.hideChat())
		{
			hideChatMessage(event);
		}
	}

	private PendingExamine createPending(MenuOptionClicked event)
	{
		MenuAction action = event.getMenuAction();
		MenuEntry entry = event.getMenuEntry();
		long now = System.currentTimeMillis();

		switch (action)
		{
			case EXAMINE_NPC:
				if (entry.getNpc() != null)
				{
					return new PendingExamine(ChatMessageType.NPC_EXAMINE, ExamineTarget.actor(entry.getNpc()), now);
				}
				break;

			case EXAMINE_OBJECT:
				TileObject object = findTileObject(entry);
				if (object != null)
				{
					return new PendingExamine(ChatMessageType.OBJECT_EXAMINE, ExamineTarget.tileObject(object), now);
				}
				break;

			case EXAMINE_ITEM_GROUND:
				ItemLayer itemLayer = findItemLayer(entry);
				if (itemLayer != null)
				{
					return new PendingExamine(ChatMessageType.ITEM_EXAMINE, ExamineTarget.tileObject(itemLayer), now);
				}
				break;

			case CC_OP_LOW_PRIORITY:
				Widget widget = findWidgetTarget(event);
				if (widget != null)
				{
					return new PendingExamine(ChatMessageType.ITEM_EXAMINE, ExamineTarget.widget(widget), now);
				}
				break;

			default:
				break;
		}

		return null;
	}

	private Widget findWidgetTarget(MenuOptionClicked event)
	{
		// Mirror RuneLite's own Examine plugin widget resolution so inventory,
		// equipment, smithing, and shop item examines bind to the item widget.
		int componentId = event.getParam1();
		int childIndex = event.getParam0();
		Widget widget = client.getWidget(componentId);
		if (widget == null)
		{
			widget = event.getWidget();
		}
		if (widget == null)
		{
			return null;
		}

		int widgetGroup = WidgetUtil.componentToInterface(componentId);
		Widget itemWidget = null;
		if (widgetGroup == InterfaceID.WORNITEMS)
		{
			itemWidget = widget.getChild(1);
		}
		else if (widgetGroup == InterfaceID.SMITHING)
		{
			itemWidget = widget.getChild(2);
		}
		else if (childIndex >= 0)
		{
			itemWidget = widget.getChild(childIndex);
		}

		if (itemWidget != null && itemWidget.getItemId() >= 0)
		{
			return itemWidget;
		}

		return widget.getItemId() >= 0 ? widget : null;
	}

	private TileObject findTileObject(MenuEntry entry)
	{
		WorldView worldView = client.getWorldView(entry.getWorldViewId());
		if (worldView == null)
		{
			return null;
		}

		Tile tile = getTile(worldView, entry.getParam0(), entry.getParam1());
		if (tile == null)
		{
			return null;
		}

		int id = entry.getIdentifier();
		WallObject wall = tile.getWallObject();
		if (objectIdEquals(wall, id))
		{
			return wall;
		}

		DecorativeObject decorative = tile.getDecorativeObject();
		if (objectIdEquals(decorative, id))
		{
			return decorative;
		}

		GroundObject ground = tile.getGroundObject();
		if (objectIdEquals(ground, id))
		{
			return ground;
		}

		for (GameObject gameObject : tile.getGameObjects())
		{
			if (objectIdEquals(gameObject, id))
			{
				return gameObject;
			}
		}
		return null;
	}

	private ItemLayer findItemLayer(MenuEntry entry)
	{
		WorldView worldView = client.getWorldView(entry.getWorldViewId());
		if (worldView == null)
		{
			return null;
		}

		Tile tile = getTile(worldView, entry.getParam0(), entry.getParam1());
		return tile == null ? null : tile.getItemLayer();
	}

	private Tile getTile(WorldView worldView, int sceneX, int sceneY)
	{
		Scene scene = worldView.getScene();
		Tile[][][] tiles = scene.getTiles();
		int plane = worldView.getPlane();
		if (plane < 0 || plane >= tiles.length || sceneX < 0 || sceneY < 0
			|| sceneX >= tiles[plane].length || sceneY >= tiles[plane][sceneX].length)
		{
			return null;
		}
		return tiles[plane][sceneX][sceneY];
	}

	private boolean objectIdEquals(TileObject tileObject, int id)
	{
		if (tileObject == null)
		{
			return false;
		}
		if (tileObject.getId() == id)
		{
			return true;
		}

		ObjectComposition composition = client.getObjectDefinition(tileObject.getId());
		if (composition != null && composition.getImpostorIds() != null)
		{
			for (int impostorId : composition.getImpostorIds())
			{
				if (impostorId == id)
				{
					return true;
				}
			}
		}
		return false;
	}

	private PendingExamine removeFirstMatching(ChatMessageType type)
	{
		Iterator<PendingExamine> iterator = pendingExamines.iterator();
		while (iterator.hasNext())
		{
			PendingExamine pending = iterator.next();
			if (pending.getResponseType() == type)
			{
				iterator.remove();
				return pending;
			}
		}
		return null;
	}

	private void prunePending(long now)
	{
		pendingExamines.removeIf(p -> now - p.getCreatedAt() > PENDING_TIMEOUT_MS);
	}

	private static boolean isExamineType(ChatMessageType type)
	{
		return type == ChatMessageType.ITEM_EXAMINE
			|| type == ChatMessageType.NPC_EXAMINE
			|| type == ChatMessageType.OBJECT_EXAMINE;
	}

	private void hideChatMessage(ChatMessage event)
	{
		if (event.getMessageNode() == null)
		{
			return;
		}

		ChatLineBuffer buffer = client.getChatLineMap().get(event.getType().getType());
		if (buffer != null)
		{
			buffer.removeMessageNode(event.getMessageNode());
			client.refreshChat();
		}
	}

	List<ActiveExamine> getActiveExamines()
	{
		return activeExamines;
	}

	void removeExpired(long now)
	{
		activeExamines.removeIf(examine ->
			examine.getExpiresAt() <= now
				|| (examine.isDismissing()
				&& now - examine.getDismissStartedAt() >= config.replacementFadeDuration()));
	}
}

package com.worldexamine;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class WorldExaminePluginTest
{
